#!/usr/bin/env node
/*
 * Builds the app's web assets from the Firefox extension's own source (a copy of it is in extension/;
 * see extension/README.md), so the app and the extension share one engine:
 *
 *   app/src/main/assets/inject/youtube.js   the script the app runs at document start on YouTube pages
 *   app/src/main/assets/{pages,shared,icons,android}/…   the Logs / Later / Settings pages
 *
 * Run it after changing anything in extension/, js/ or web/:  node tools/bundle.js
 * `node tools/bundle.js --check` fails if the committed assets are out of date (used by the tests).
 */
'use strict';
const fs = require('fs');
const path = require('path');

const ANDROID = path.join(__dirname, '..');
// The extension's source: the copy in this repository, or another checkout of it (OTAAT_EXTENSION=path).
const EXT = process.env.OTAAT_EXTENSION ? path.resolve(process.env.OTAAT_EXTENSION) : path.join(ANDROID, 'extension');
const OUT = path.join(ANDROID, 'app', 'src', 'main', 'assets');

const ext = (rel) => fs.readFileSync(path.join(EXT, rel), 'utf8');
const own = (rel) => fs.readFileSync(path.join(ANDROID, rel), 'utf8');

const HEADER = '/* Generated by android/tools/bundle.js from the extension and android/js. Do not edit. */\n';

// Where the app puts the user's settings (JSON) before handing the script to the WebView.
const SETTINGS_SLOT = '/*@SETTINGS@*/null';
// … and the secret every message to the app must carry.
const TOKEN_SLOT = "'@TOKEN@'";

// Sources are pasted in as they are (no re-indenting: that would change multi-line strings).
const indent = (text) => text;

function injectScript() {
  const parts = [
    ['android/js/shim.js', own('js/shim.js')],
    ['extension/shared/settings.js', ext('shared/settings.js')],
    ['extension/content/core.js', ext('content/core.js')],
    ['android/js/ui.js', own('js/ui.js')],
    ['extension/content/sites/youtube.js', ext('content/sites/youtube.js')],
    ['android/js/youtube-app.js', own('js/youtube-app.js')],
    ['extension/content/engine.js', ext('content/engine.js')],
  ];
  const body = parts.map(([name, src]) => `    // ---- ${name}\n${indent(src)}`).join('\n');
  return (
    HEADER +
    `(function () {
  'use strict';
  // Only the top page, and only where the app opened its message channel (YouTube's own origins).
  if (window.top !== window) return;
  const port = window.otaatNative;
  if (!port || window.__otaatApp) return;
  Object.defineProperty(window, '__otaatApp', { value: true });
  try {
    delete window.otaatNative; // only this script keeps it
  } catch (_) {
    /* not deletable here: the token still keeps page scripts out */
  }
  const TOKEN = ${TOKEN_SLOT};
  const OTAAT_INITIAL_SETTINGS = ${SETTINGS_SLOT};
  const HIDE_CSS = ${JSON.stringify(ext('content/hide.css') + String.fromCharCode(10) + own('js/app.css'))};

  function boot() {
    // The hiding rules, in place before the page draws anything. Put back if the page ever removes them.
    const style = document.createElement('style');
    style.setAttribute('data-otaat', '');
    style.textContent = HIDE_CSS;
    const place = () => {
      const root = document.documentElement;
      if (root && style.parentNode !== root) root.insertBefore(style, root.firstChild);
    };
    place();
    new MutationObserver(place).observe(document.documentElement, { childList: true });

    // ---- extension/content/yt-main.js (YouTube page bridge: Watch Later, player data)
${indent(ext('content/yt-main.js'))}

    (function (globalThis) {
${body}
    // Tests only: hands the engine to the test harness (set before this script; pages can't, it runs first).
    if (typeof window.__otaatTestHook === 'function') window.__otaatTestHook(globalThis.OTAAT);
    })(Object.create(null));
  }

  if (document.documentElement) boot();
  else {
    // Not created yet: start the moment it is (before anything can be drawn).
    const wait = new MutationObserver(() => {
      if (!document.documentElement) return;
      wait.disconnect();
      boot();
    });
    wait.observe(document, { childList: true });
  }
})();
`
  );
}

function must(text, needle, file) {
  if (!text.includes(needle)) throw new Error(`bundle: expected to find ${JSON.stringify(needle)} in ${file}`);
}

function pageHtml(name) {
  let html = ext(`pages/${name}`);
  must(html, '<script src="../shared/format.js"></script>', name);
  must(html, '<script src="common.js"></script>', name);
  html = html
    .replace('<script src="../shared/format.js"></script>', '<script src="../android/pages-shim.js"></script>\n  <script src="../shared/format.js"></script>')
    .replace('<script src="common.js"></script>', '<script src="common.js"></script>\n  <script src="../android/pages-after.js"></script>');
  if (name === 'later.html') {
    const yt = /<div class="panel yt">[\s\S]*?<\/div>/;
    if (!yt.test(html)) throw new Error('bundle: YouTube panel not found in later.html');
    html = html.replace(
      yt,
      `<div class="panel yt">
      <p><b>YouTube:</b> videos you send to Later go straight into your YouTube <b>Watch later</b> playlist.
        If YouTube refuses or doesn't answer, they are kept on the Later list below instead.</p>
      <a class="button primary" href="https://m.youtube.com/playlist?list=WL">Open Watch later</a>
    </div>

    <div class="panel" id="upnext">
      <h2>Up next <span class="muted small" id="queueCount"></span></h2>
      <p class="muted small" style="margin-top:-4px">Videos you <b>Queue</b>. When a video ends, the first one here plays. They stay in the queued log after they have played.</p>
      <div id="queueList"></div>
    </div>`
    );
    html = html.replace('<script src="later.js"></script>', '<script src="later.js"></script>\n  <script src="../android/queue.js"></script>');
  }
  return html;
}

function build() {
  const files = new Map();
  files.set('inject/youtube.js', injectScript());
  files.set('shared/format.js', ext('shared/format.js'));
  files.set('shared/settings.js', ext('shared/settings.js'));
  files.set('icons/icon.svg', ext('icons/icon.svg'));
  for (const f of ['common.css', 'common.js', 'later.js']) files.set(`pages/${f}`, ext(`pages/${f}`));
  // The Logs page's note for phones is about Firefox; in the app, files are written once a folder is chosen.
  const FIREFOX_NOTE =
    "'On Firefox for Android everything is kept here, in Firefox. Use Export or Copy above to save it, and do so now and then: logs kept only in Firefox are lost if the extension is removed.'";
  const logsJs = ext('pages/logs.js');
  must(logsJs, FIREFOX_NOTE, 'logs.js');
  files.set(
    'pages/logs.js',
    logsJs.replace(FIREFOX_NOTE, "'No log folder chosen yet. Everything is kept safely in the app; choose a folder in Settings and it is all written there.'")
  );
  for (const f of ['logs.html', 'later.html']) files.set(`pages/${f}`, pageHtml(f));
  for (const f of fs.readdirSync(path.join(ANDROID, 'web', 'pages'))) files.set(`pages/${f}`, own(`web/pages/${f}`));
  for (const f of fs.readdirSync(path.join(ANDROID, 'web', 'android'))) files.set(`android/${f}`, own(`web/android/${f}`));
  return files;
}

function main() {
  const check = process.argv.includes('--check');
  const files = build();
  const stale = [];
  for (const [rel, text] of files) {
    const dest = path.join(OUT, rel);
    const current = fs.existsSync(dest) ? fs.readFileSync(dest, 'utf8') : null;
    if (current === text) continue;
    stale.push(rel);
    if (!check) {
      fs.mkdirSync(path.dirname(dest), { recursive: true });
      fs.writeFileSync(dest, text);
    }
  }
  if (check && stale.length) {
    console.error(`Assets out of date (run node tools/bundle.js): ${stale.join(', ')}`);
    process.exit(1);
  }
  console.log(check ? 'Assets up to date.' : stale.length ? `Wrote ${stale.join(', ')}` : 'Assets already up to date.');
}

module.exports = { build, SETTINGS_SLOT, TOKEN_SLOT };
if (require.main === module) main();
